import akka.actor.ActorSystem
import akka.http.scaladsl.Http
import akka.http.scaladsl.model._
import akka.http.scaladsl.server.Directives._
import akka.http.scaladsl.server.Route
import javax.crypto.Cipher
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.security.{MessageDigest, SecureRandom}
import java.util.Base64
import java.util.concurrent.atomic.{AtomicBoolean, AtomicReference}
import scala.concurrent.{ExecutionContext, Future}
import scala.concurrent.duration._

object ApiServer extends App {

  implicit val system: ActorSystem = ActorSystem("api-server")
  implicit val ec: ExecutionContext = system.dispatcher

  private val shutdownRequested = new AtomicBoolean(false)
  private val activeConnections = new AtomicReference[Int](0)

  // Shutdown authorization token - must be supplied via environment.
  // If unset, the shutdown endpoint is disabled to avoid unauthenticated DoS.
  private val shutdownToken: Option[String] =
    sys.env.get("SHUTDOWN_TOKEN").filter(_.nonEmpty)

  // Constant-time comparison to avoid timing side channels on the token.
  private def tokenMatches(provided: String): Boolean = shutdownToken.exists { expected =>
    MessageDigest.isEqual(
      expected.getBytes("UTF-8"),
      provided.getBytes("UTF-8")
    )
  }

  // Key management with rotation support
  private val keyStore = new CryptoKeyStore()

  class CryptoKeyStore {
    private val random = new SecureRandom()
    private val keySize = 256
    private val ivSize = 12
    private val tagSize = 128

    // Current encryption key - always fresh on startup
    @volatile private var currentKey: Array[Byte] = generateKey()
    @volatile private var currentKeyId: String = generateKeyId()

    // Nonce uses random generation for each encryption
    private val nonceCounter = new AtomicReference[Long](0L)

    private def generateKey(): Array[Byte] = {
      val key = new Array[Byte](keySize / 8)
      random.nextBytes(key)
      key
    }

    private def generateKeyId(): String = {
      val id = new Array[Byte](8)
      random.nextBytes(id)
      Base64.getUrlEncoder.withoutPadding().encodeToString(id)
    }

    def rotateKey(): Unit = {
      currentKey = generateKey()
      currentKeyId = generateKeyId()
      nonceCounter.set(0L)
    }

    def getKeyId: String = currentKeyId

    def encrypt(plaintext: Array[Byte]): EncryptedPayload = {
      val nonce = generateRandomNonce()
      val cipher = Cipher.getInstance("AES/GCM/NoPadding")
      val keySpec = new SecretKeySpec(currentKey, "AES")
      val gcmSpec = new GCMParameterSpec(tagSize, nonce)
      cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)
      val ciphertext = cipher.doFinal(plaintext)
      EncryptedPayload(currentKeyId, Base64.getEncoder.encodeToString(nonce), Base64.getEncoder.encodeToString(ciphertext))
    }

    def decrypt(payload: EncryptedPayload): Array[Byte] = {
      val nonce = Base64.getDecoder.decode(payload.nonce)
      val ciphertext = Base64.getDecoder.decode(payload.ciphertext)
      val cipher = Cipher.getInstance("AES/GCM/NoPadding")
      val keySpec = new SecretKeySpec(currentKey, "AES")
      val gcmSpec = new GCMParameterSpec(tagSize, nonce)
      cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec)
      cipher.doFinal(ciphertext)
    }

    private def generateRandomNonce(): Array[Byte] = {
      val nonce = new Array[Byte](ivSize)
      random.nextBytes(nonce)
      nonce
    }
  }

  case class EncryptedPayload(keyId: String, nonce: String, ciphertext: String)

  // Graceful shutdown handler - drains connections then rotates keys
  private def initiateGracefulShutdown(): Future[Unit] = {
    shutdownRequested.set(true)
    Future {
      // Wait for active connections to drain (max 30s)
      val deadline = System.currentTimeMillis() + 30000
      while (activeConnections.get() > 0 && System.currentTimeMillis() < deadline) {
        Thread.sleep(100)
      }
      // Rotate key - old key material is discarded
      keyStore.rotateKey()
    }
  }

  // Shutdown hook for SIGTERM handling
  sys.addShutdownHook {
    // On abrupt shutdown, we do NOT persist key material
    // Next startup always generates fresh keys
    cleanupTempFiles()
  }

  private def cleanupTempFiles(): Unit = {
    val stateFile = new java.io.File("/tmp/.api-server-key-state")
    if (stateFile.exists()) {
      stateFile.delete()
    }
  }

  val route: Route = {
    path("encrypt") {
      post {
        entity(as[String]) { body =>
          activeConnections.updateAndGet(_ + 1)
          val result = keyStore.encrypt(body.getBytes("UTF-8"))
          activeConnections.updateAndGet(_ - 1)
          complete(HttpEntity(ContentTypes.`application/json`,
            s"""{ "keyId": "${result.keyId}", "nonce": "${result.nonce}", "ciphertext": "${result.ciphertext}" }"""))
        }
      }
    } ~
    path("shutdown") {
      post {
        // Require a valid bearer token to prevent unauthenticated shutdown (DoS).
        optionalHeaderValueByName("Authorization") { authHeader =>
          val provided = authHeader.map(_.stripPrefix("Bearer ").trim).getOrElse("")
          if (shutdownToken.isDefined && tokenMatches(provided)) {
            onSuccess(initiateGracefulShutdown()) {
              complete(StatusCodes.OK, "Shutdown complete")
            }
          } else {
            complete(StatusCodes.Unauthorized, "Unauthorized")
          }
        }
      }
    } ~
    path("health") {
      get {
        if (shutdownRequested.get()) {
          complete(StatusCodes.ServiceUnavailable, "Shutting down")
        } else {
          complete(StatusCodes.OK, "OK")
        }
      }
    }
  }

  Http().newServerAt("0.0.0.0", 8443).bind(route)
}
